"""Real game verification of selected Siege Console, viewport, live seats and aim."""
from pathlib import Path
from playwright.sync_api import sync_playwright
from PIL import Image
import shoot,json,hashlib,sys
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'_shots/siege_console_1012';OUT.mkdir(parents=True,exist_ok=True)
checks=[];errors=[]
def check(name,ok,data=None):
 checks.append(dict(name=name,passed=bool(ok),data=data));print(('PASS ' if ok else 'FAIL ')+name+((' '+json.dumps(data)) if not ok else ''),flush=True)
art=json.loads((ROOT/'assets/game/shared/ui/siege_console_1012/registration.json').read_text(encoding='utf-8'))
pictures=[ROOT/art['path'],ROOT/'_ART_SOURCES/side_hud_1012/siege-console.png']
check('Shipping plate is byte-identical to the approved 1024x1536 RGBA source',all(hashlib.sha256(p.read_bytes()).hexdigest()==art['sha256'] for p in pictures) and Image.open(pictures[0]).size==(1024,1536))
check('Maneuver meters belong to their matching left/right maneuver boxes',art['wells']['rollBar'][0]<art['wells']['somerBar'][0])
port,stop=shoot.serve(str(ROOT))
try:
 with sync_playwright() as pw:
  br=pw.chromium.launch(args=['--mute-audio','--autoplay-policy=no-user-gesture-required']);p=br.new_page(viewport=dict(width=1920,height=1080));p.set_default_timeout(120000)
  p.on('pageerror',lambda e:errors.append(str(e)))
  p.on('console',lambda m:errors.append(m.text[:600]) if m.type=='error' or 'draw error' in m.text else None)
  p.on('response',lambda r:errors.append(str(r.status)+' '+r.url) if r.status>=400 else None)
  p.goto(f'http://127.0.0.1:{port}/index.html');p.wait_for_function('window.__bofFrames>4');p.evaluate(shoot.TRAP_RAF);p.wait_for_timeout(40)
  p.evaluate(shoot.SETUP,dict(state='PLAY',stage=1,pilot='cole',invuln=True))
  p.wait_for_function('()=>{stageLoadTick();return stageLoadReady(1)&&XART.rdy(SC12_ART.key)&&bmfReady("game")&&fs11ArtReady("cole")}',polling=50)
  p.evaluate('''()=>{run.lives=7;run.bombs=18;run.score=123456;player.invuln=0;player._rollCool=BR_COOL*.5;player._somerCool=SS_COOL*.75;player.x=240;player.y=410;
    window.sc12PlateCalls=0;for(const c of SC12.panels){const g=c.getContext('2d'),draw=g.drawImage;g.drawImage=function(){sc12PlateCalls++;return draw.apply(this,arguments);};}
    SC12.refresh();}''')
  def render():
   p.evaluate('()=>{ctx.setTransform(SS,0,0,SS,0,0);if(state==="play")drawWorld(0);SC12.refresh();window.__bofFit();}')
  def snap(name):render();p.screenshot(path=str(OUT/(name+'.png')))
  snap('stage1-live')
  q=p.evaluate('({mode:SC12.mode,field:SC12.layout.field,values:SC12.last,calls:sc12PlateCalls,artReady:XART.rdy(SC12_ART.key)})')
  check('Approved authored plate renders through the native HUD contexts and XART',q['artReady'] and q['calls']>40,q)
  check('Live score, lives, missiles and cooldown fractions reach the side HUD',q['values'][0]['score']==123456 and q['values'][0]['lives']==7 and q['values'][0]['missiles']==18 and abs(q['values'][0]['roll']-.5)<.001 and abs(q['values'][0]['somer']-.25)<.001,q['values'])
  p.evaluate('()=>{startSpecial();special.t=special.dur*.5;special.strikes=2;SC12.refresh();}')
  snap('active-special')
  check('Active signature resource and remaining strikes update the special panel',p.evaluate('SC12.last[0].resource===.5&&SC12.last[0].detail==="NUKES 2"'))
  p.evaluate('endSpecial()')
  check('Wide playfield fills the height at its native aspect',q['mode']=='sides' and q['field']['h']==1080 and abs(q['field']['w']/q['field']['h']-480/512)<.0001,q['field'])
  check('Old top/bottom HUD and credit rails consume no layout space',p.evaluate('()=>["hud-row","hud-bottom","hud-div","hud-div2","credit-left","credit-right","hint"].every(id=>getComputedStyle(document.getElementById(id)).display==="none")'))
  p.evaluate('''()=>{enemies=[];boss=subBoss=null;bossActive=subBossActive=false;camX=0;const e=spawnEnemy('jet',240,190,{});e.x=240;e.y=190;e.frCloak=false;SC12.refresh();}''')
  check('Radar plots actual visible enemies and the player',p.evaluate('SC12.contacts.some(q=>q.kind==="enemy")&&SC12.contacts.some(q=>q.kind==="player")'))
  p.evaluate('()=>{enemies[0].frCloak=true;SC12.refresh();}')
  check('Cloaked enemy does not leak into radar',p.evaluate('!SC12.contacts.some(q=>q.kind==="enemy")'))
  p.evaluate('()=>{enemies=[];playerLocks=[{seat:1,state:"locked"}];SC12.refresh();}')
  check('Retina lock changes the native right panel',p.evaluate('SC12.last[0].lock'))
  p.evaluate('()=>{playerLocks=[];run.lives=1;run.bombs=0;SC12.refresh();}');snap('low-stocks')
  check('Low and empty stock values display without being clamped to a fake minimum',p.evaluate('SC12.last[0].lives===1&&SC12.last[0].missiles===0'))
  geometry=[]
  for st in ['intro','launch','play','paused','continue','gameover']:
   p.evaluate('s=>{setState(s);stateT=.6;}',st)
   err=p.evaluate(shoot.STEP,1)
   if err:errors.append(err)
   render();q=p.evaluate('()=>{const r=cv.getBoundingClientRect();return {state,field:[r.x,r.y,r.width,r.height],backing:[cv.width,cv.height],mode:SC12.mode};}');geometry.append(q)
   check(st+' retains the full-height gameplay field and native backing',q['mode']=='sides' and abs(q['field'][3]-1080)<1 and q['backing']==[960,1024],q)
   p.screenshot(path=str(OUT/(st+'-scene.png')))
  check('Fly-in, gameplay, pause, continue and gameover share identical screen geometry',all(q['field']==geometry[0]['field'] for q in geometry),geometry)
  p.evaluate('()=>{setState("play");stateT=2;SC12.refresh();stateT=2.1;SC12.refresh();window.sc12RadarBeforePause=SC12.clock;setState("paused");}')
  p.evaluate(shoot.STEP,15)
  check('Pause freezes the radar clock',p.evaluate('SC12.clock===sc12RadarBeforePause'))
  p.evaluate('()=>{setState("play");run.lives=3;run.bombs=12;}')
  p.locator('#fs-btn').click();p.wait_for_function('document.fullscreenElement!==null');p.evaluate('window.__bofFit()');p.wait_for_timeout(120);snap('fullscreen')
  check('Native fullscreen has the same playfield size and hides old operations panels',p.evaluate('SC12.layout.field.h===1080&&["wide-left","wide-right","wide-clock"].every(id=>getComputedStyle(document.getElementById(id)).display==="none")'))
  p.evaluate('document.exitFullscreen()');p.wait_for_timeout(100)
  for width,height in [(2560,1080),(1920,1080),(1280,720),(1280,1000),(820,900),(480,900),(390,844)]:
   p.set_viewport_size(dict(width=width,height=height));p.evaluate('window.__bofFit();SC12.refresh()')
   q=p.evaluate('()=>{const nodes=SC12.mode==="sides"?[cv,...SC12.panels]:[cv,SC12.compact];return {mode:SC12.mode,boxes:nodes.map(n=>{const r=n.getBoundingClientRect();return [r.x,r.y,r.width,r.height];}),field:SC12.layout.field};}')
   check(f'Field and authored HUD stay inside {width}x{height}',all(a>=-1 and b>=-1 and a+c<=width+1 and b+d<=height+1 for a,b,c,d in q['boxes']) and abs(q['field']['w']/q['field']['h']-480/512)<.0001,q)
   field=q['field'];p.mouse.move(field['x']+field['w']*.7,field['y']+field['h']*.35)
   pointer=p.evaluate('({x:Input.mouse.x,y:Input.mouse.y})')
   check(f'Mouse input maps to the visible field at {width}x{height}',abs(pointer['x']-480*.7)<1 and abs(pointer['y']-512*.35)<1,pointer)
   p.screenshot(path=str(OUT/f'fit-{width}x{height}.png'))
  p.set_viewport_size(dict(width=1920,height=1080));p.evaluate('window.__bofFit()')
  # Live native bindings for all nine pilots, including enhanced special icon routing.
  for pk in ['yuri','falva','cole','maverick','axel','juggernaut','lizzie','decker','freezer']:
   p.evaluate('pk=>{run.pilot=pk;pilotIndex=PILOTS.findIndex(q=>q.key===pk);const q=PILOTS[pilotIndex];PILOTMOD={spd:q.spd||0,fire:q.fire||0,range:q.range||0,tint:q.tint};run.lives=4;run.bombs=9;fs11Warm(pk);}',pk)
   p.wait_for_function('()=>fs11ArtReady(run.pilot)',polling=50);p.evaluate('SC12.refresh()')
   p.wait_for_function('()=>{const g=document.createElement("canvas").getContext("2d");return ["nli_"+pilotIndex,"nmi_"+pilotIndex,weaponIconKey(run.weapon,1)].every(k=>!!iconBlit(g,k,64,64,40,true));}',polling=50)
   p.evaluate('SC12.refresh()');p.screenshot(path=str(OUT/('pilot-'+pk+'.png')))
   check(pk+' exposes its native weapon and signature special readouts',p.evaluate('SC12.last[0].pilot')==pk and bool(p.evaluate('SC12.last[0].name')) and p.evaluate('SC12.last[0].lives')==4)
  p.evaluate('()=>{run.pilot="maverick";pilotIndex=PILOTS.findIndex(q=>q.key===run.pilot);run.weapon=3;run.wlevel=5;run.wvars={...run.wvars,3:"mavhoming"};run.forge={...run.forge};delete run.forge[3];SC12.refresh();}')
  snap('maverick-fixed-lances')
  check('Maverick homing lances show fixed Level I without changing his beam bank',p.evaluate('SC12.last[0].weaponFixed&&SC12.last[0].weapon.lv===1&&SC12.last[0].weaponName==="HOMING LANCES"&&run.wlevel===5'))
  p.evaluate('()=>{run.wvars[3]="laserbeam";SC12.refresh();}')
  check('Maverick separate Laser Beam retains its equipped upgrade level',p.evaluate('!SC12.last[0].weaponFixed&&SC12.last[0].weapon.lv===5&&SC12.last[0].weaponName==="LASER BEAM"'))
  p.evaluate('()=>{run.weapon=0;run.wlevel=1;}')
  p.evaluate('''()=>{run.pilot='cole';coopOn=true;run2.pilot='maverick';run2.lives=2;run2.bombs=5;run2.score=98765;player2.dead=false;player2._rollCool=BR_COOL*.7;run.lives=8;run.bombs=19;run.score=765432;window.__bofFit();SC12.refresh();}''')
  snap('coop-live')
  q=p.evaluate('({values:SC12.last,field:SC12.layout.field,seat:_seat,pilot:run.pilot})')
  check('Co-op keeps independent stocks and scores in both side columns',len(q['values'])==2 and q['values'][0]['lives']==8 and q['values'][0]['missiles']==19 and q['values'][1]['lives']==2 and q['values'][1]['missiles']==5 and q['values'][1]['score']==98765,q)
  check('Drawing co-op HUD restores the active seat and keeps a full-height field',q['seat']==1 and q['pilot']=='cole' and q['field']['h']==1080,q)
  check('Both co-op score panels share the highest live score',p.evaluate('SC12.highScore')==765432)
  p.set_viewport_size(dict(width=390,height=844));p.evaluate('window.__bofFit();SC12.refresh()');p.screenshot(path=str(OUT/'coop-compact.png'))
  check('Co-op compact HUD remains inside the narrow window',p.evaluate('()=>{const r=SC12.compact.getBoundingClientRect();return r.x>=0&&r.right<=innerWidth+.1&&r.bottom<=innerHeight+.1;}'))
  p.evaluate('()=>{coopOn=false;setState("title");}');p.wait_for_timeout(100)
  check('Returning to menus releases side HUD layout ownership',p.evaluate('!SC12.active()&&!document.body.classList.contains("siege-console")&&getComputedStyle(SC12.compact).display==="none"'))
  check('No page, console or missing-asset errors',not errors,errors);br.close()
finally:stop()
report=dict(passed=sum(q['passed'] for q in checks),failed=sum(not q['passed'] for q in checks),errors=errors,checks=checks)
(ROOT/'docs/qa/siege_console_1012.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
(OUT/'verification.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
print(json.dumps(dict(passed=report['passed'],failed=report['failed'],errors=errors)),flush=True)
sys.exit(bool(report['failed']))
